do $$ declare n int; begin
  select count(*) into n from _ren r join public.biomarker_hub h on h.name = r.new;
  if n > 0 then raise exception 'Rename aborted: % target names already exist', n; end if;
end $$;
update public.biomarker_hub h set name = r.new,
  synonyms = array(select distinct on (lower(x)) x from unnest(coalesce(h.synonyms,'{}'::text[]) || array[r.old]) x order by lower(x), x), last_updated = now()
  from _ren r where h.name = r.old and h.status = 'active';
