update public.biomarker_hub h set synonyms = array(select distinct on (lower(x)) x from unnest(coalesce(h.synonyms,'{}'::text[]) || a.syns) x where lower(x) <> lower(h.name) order by lower(x), x), last_updated = now()
  from (select name, array_agg(syn) syns from _syn group by name) a where h.name = a.name and h.status = 'active';
update public.biomarker_hub set abbreviation = substr(name, 1, length(name) - 5), last_updated = now() where status = 'active' and name in ('APC gene','ATM gene','BMPR1A gene','BRCA1 gene','BRCA2 gene','CDH1 gene','CHEK2 gene','EPCAM gene','MLH1 gene','MSH2 gene','MSH6 gene','MUTYH gene','PALB2 gene','PMS2 gene','POLD1 gene','POLE gene','PTEN gene','RAD51C gene','RAD51D gene','SMAD4 gene','STK11 gene','TP53 gene') and nullif(btrim(abbreviation),'') is null;
