create temp table _ctx(pid text, test text, label text, target text) on commit drop;
insert into _ctx values ('medichecks','Microscopy and Culture (UTI) Urine Test','Red blood cells','Red Blood Cells (Urine)'),('medichecks','Microscopy and Culture (UTI) Urine Test','Glucose','Glucose (Urine)'),('medichecks','Microscopy and Culture (UTI) Urine Test','Protein','Urine Protein');
update public.provider_test_biomarkers b set biomarker_id = h.id, match_method = 'exact_synonym'
  from _ctx x join public.provider_tests t on t.provider_id = x.pid and t.test_name = x.test
  join public.biomarker_hub h on h.name = x.target and h.status = 'active'
 where b.provider_test_id = t.id and b.raw_label = x.label and b.biomarker_id is distinct from h.id;
insert into public.known_scrape_junk_labels (label, reason) select v.l, v.r from (values ('Alt','Image alt-text captured as a biomarker on Randox DNA and microbiome pages; matched ALT in error'),('Early detection','Marketing phrase captured as the only biomarker of a Medical Diagnosis test'),('F-','Truncated allergen code with no allergen name')) v(l, r) where not exists (select 1 from public.known_scrape_junk_labels j where j.label = v.l);
